// handleMemoryFacetCandidates returns compact repository-wide filter evidence.
// The BFF applies the same reachability policy as the repository memory list.
func (s *Server) handleMemoryFacetCandidates(w http.ResponseWriter, r *http.Request) {
	_, repoID, ok := s.guard(w, r, false)
	if !ok {
		return
	}
	const maxCandidates = 10000
	candidates, err := s.store.MemoryFacetCandidates(r.Context(), repoID, maxCandidates+1)
	if err != nil {
		s.logger.Error().Err(err).Msg("memory facet candidates")
		writeJSONError(w, http.StatusInternalServerError, "internal error")
		return
	}
	if len(candidates) > maxCandidates {
		writeJSONError(w, http.StatusServiceUnavailable, "memory facets exceed 10000 candidates")
		return
	}
	writeJSON(w, http.StatusOK, struct {
		Items []store.MemoryFacetCandidate `json:"items"`
	}{Items: candidates})
}

